<?php defined( 'ABSPATH' ) || exit; if ( ! is_user_logged_in() && 'yes' === get_option( 'woocommerce_enable_checkout_login_reminder' ) ) { do_action( 'woocommerce_before_checkout_form', $checkout ); } else { do_action( 'woocommerce_before_checkout_form', $checkout ); } ?><div class="container checkout-page"><div class="shop-breadcrumbs"><?php souqify_breadcrumbs(); ?></div><h1><?php esc_html_e( 'Checkout', 'souqify' ); ?></h1><form name="checkout" method="post" class="checkout woocommerce-checkout" action="<?php echo esc_url( wc_get_checkout_url() ); ?>" enctype="multipart/form-data"><div class="checkout-layout"><div class="checkout-details"><?php if ( $checkout->get_checkout_fields() ) : ?><div id="customer_details"><?php do_action( 'woocommerce_checkout_billing' ); ?><?php do_action( 'woocommerce_checkout_shipping' ); ?></div><?php endif; ?></div><div class="checkout-summary"><?php do_action( 'woocommerce_checkout_order_review' ); ?></div></div></form></div><?php do_action( 'woocommerce_after_checkout_form', $checkout ); ?>
